package vn.gasstation.integration.seenpro.parser;
import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class SeenProRevenueReportHtmlParserTest {@Test void parsesSummaryAndThreeBusinessGroups(){String html="""
<html><head><title>Báo Cáo Doanh Thu</title></head><body><div class="today-left"><div class="info"><div class="content">100000</div></div><div class="info"><div class="content">4.5</div></div><div class="info"><div class="content">2</div></div><div class="info"><div class="content">90000</div></div><div class="info"><div class="content">4</div></div><div class="info"><div class="content">1</div></div></div><div class="baocaochitiet"><div class="boxGas"><div class="boxData"><div class="rowx color4"><div class="colx">RON95</div><div class="colx">4.5</div><div class="colx">100.000</div><div class="colx">2</div></div></div></div><div class="boxGas"><div class="boxData"><div class="rowx color4"><div class="colx">Cột 01</div><div class="colx">4.5</div><div class="colx">100.000</div><div class="colx">2</div></div></div></div><div class="boxGas"><div class="boxData"><div class="rowx color4"><div class="colx">RON95</div><div class="colx">90.000</div><div class="colx">4</div><div class="colx">1</div></div></div></div></div></body></html>""";var report=new SeenProRevenueReportHtmlParser().parse(html);assertThat(report.todayValues()).hasSize(6);assertThat(report.fuels()).hasSize(1);assertThat(report.pumps()).hasSize(1);assertThat(report.invoices()).hasSize(1);assertThat(report.invoices().getFirst().revenue()).isEqualTo("90.000");}}
